45	/**
46	 * Report a warning.
47	 *
48	 * `code` is stable and meant for matching; `message` is a sentence for a
49	 * person. Everything else in `facts` travels on the event as it is.
50	 */
51	export function warn(code, message, { element = null, doc = null, ...facts } = {}) {
52	  const document = doc ?? element?.ownerDocument ?? globalThis.document ?? null;
53	  const detail = { code, message, element, ...facts };
54	
55	  if (document === null) {
56	    console.warn(message, detail);
57	    return detail;
58	  }
59	
60	  const view = document.defaultView ?? globalThis;
61	  const event = new view.CustomEvent(WARNING_EVENT, { bubbles: true, cancelable: true, detail });
62	  const from = element !== null && element.isConnected ? element : document;
63	  if (!from.dispatchEvent(event)) return detail;
64	
65	  const lists = [...document.querySelectorAll(`[${WARNINGS_ATTR}]`)];
66	  if (lists.length === 0) {
67	    console.warn(message, detail);
68	    return detail;
69	  }
70	
71	  for (const list of lists) {
72	    const item = document.createElement('li');
73	    item.setAttribute(WARNING_ATTR, code);
74	    item.textContent = message;
75	    list.append(item);
76	    // Only its own items: whatever else the host put in the list stays.
77	    const kept = list.querySelectorAll(`:scope > [${WARNING_ATTR}]`);
78	    for (let index = 0; index < kept.length - KEPT; index += 1) kept[index].remove();
79	  }
80	  return detail;
81	}
